import Foundation

/// What dicavo.eu publishes about the newest bridge.
///
/// The bridge is the one product outside the App Store, so it has to find
/// out about its own updates. The manifest is a static file generated by
/// `web/build.py` next to the download it describes; trust in the download
/// itself comes from its code signature, checked by `BridgeUpdateInstaller`,
/// not from this file. The manifest only has to be precise enough that the
/// bridge never fetches anything from anywhere but dicavo.eu, and can tell
/// the file it fetched is the one that was published.
struct BridgeUpdateManifest: Codable, Equatable, Sendable {
    static let schemaVersion = 1
    static let feedURL = URL(string: "https://dicavo.eu/bridge/latest.json")!
    static let trustedHost = "dicavo.eu"
    /// A manifest is a few hundred bytes; anything this large is not one.
    static let maximumManifestBytes = 64 * 1024
    /// The notarised image is under half a megabyte today.
    static let maximumImageBytes: Int64 = 50 * 1024 * 1024

    var schemaVersion: Int
    /// `CFBundleShortVersionString` of the published build, for display.
    var version: String
    /// `CFBundleVersion` of the published build. The only thing compared:
    /// it is an integer that never decreases on a branch.
    var build: Int
    var minimumSystemVersion: String
    var url: URL
    var sha256: String
    var size: Int64
    var releaseNotesURL: URL?

    static func decode(_ data: Data) throws -> BridgeUpdateManifest {
        guard data.count <= maximumManifestBytes else { throw BridgeUpdateError.malformedManifest }
        let manifest: BridgeUpdateManifest
        do {
            manifest = try JSONDecoder().decode(BridgeUpdateManifest.self, from: data)
        } catch {
            throw BridgeUpdateError.malformedManifest
        }
        try manifest.validate()
        return manifest
    }

    func validate() throws {
        guard schemaVersion == Self.schemaVersion else { throw BridgeUpdateError.unsupportedManifest }
        guard Self.isTrusted(url) else { throw BridgeUpdateError.untrustedURL }
        if let releaseNotesURL, !Self.isTrusted(releaseNotesURL) { throw BridgeUpdateError.untrustedURL }
        guard sha256.count == 64, sha256.allSatisfy(\.isHexDigit) else { throw BridgeUpdateError.malformedManifest }
        guard build > 0, !version.isEmpty else { throw BridgeUpdateError.malformedManifest }
        guard size > 0, size <= Self.maximumImageBytes else { throw BridgeUpdateError.malformedManifest }
        guard Self.systemVersion(minimumSystemVersion) != nil else { throw BridgeUpdateError.malformedManifest }
    }

    /// HTTPS on dicavo.eu itself: no other host, no other port, no
    /// credentials in the URL.
    static func isTrusted(_ url: URL) -> Bool {
        guard url.scheme?.lowercased() == "https",
              url.host?.lowercased() == trustedHost,
              url.user == nil, url.password == nil
        else { return false }
        return url.port == nil || url.port == 443
    }

    /// "14", "14.2" or "14.2.1"; anything else is not a version.
    static func systemVersion(_ string: String) -> OperatingSystemVersion? {
        let parts = string.split(separator: ".", omittingEmptySubsequences: false)
        guard (1...3).contains(parts.count) else { return nil }
        var numbers: [Int] = []
        for part in parts {
            guard !part.isEmpty, part.allSatisfy(\.isASCII), let number = Int(part), number >= 0 else { return nil }
            numbers.append(number)
        }
        while numbers.count < 3 { numbers.append(0) }
        return OperatingSystemVersion(majorVersion: numbers[0], minorVersion: numbers[1], patchVersion: numbers[2])
    }

    func availability(currentBuild: Int, system: OperatingSystemVersion) -> BridgeUpdateAvailability {
        guard build > currentBuild else { return .upToDate }
        guard let minimum = Self.systemVersion(minimumSystemVersion), Self.system(system, isAtLeast: minimum) else {
            return .requiresNewerSystem(self)
        }
        return .available(self)
    }

    static func system(_ system: OperatingSystemVersion, isAtLeast minimum: OperatingSystemVersion) -> Bool {
        (system.majorVersion, system.minorVersion, system.patchVersion)
            >= (minimum.majorVersion, minimum.minorVersion, minimum.patchVersion)
    }
}

enum BridgeUpdateAvailability: Equatable, Sendable {
    case upToDate
    case available(BridgeUpdateManifest)
    /// Newer, but this Mac cannot run it. Offered for information only.
    case requiresNewerSystem(BridgeUpdateManifest)
}

/// What the bridge tells Dicavo about a manifest a check returned: the
/// version to offer and, when this Mac cannot run it, the macOS it needs.
/// Plain values, because `BridgeUpdateSummary` lives with the descriptor,
/// which the targets that compile this file do not all share.
struct BridgeUpdateOffer: Equatable, Sendable {
    var version: String
    var requiredSystemVersion: String?
}

extension BridgeUpdateManifest {
    /// Nil once the running build has caught up with this manifest, as after
    /// the update was installed.
    func offer(currentBuild: Int, system: OperatingSystemVersion) -> BridgeUpdateOffer? {
        switch availability(currentBuild: currentBuild, system: system) {
        case .available:
            return BridgeUpdateOffer(version: version)
        case .requiresNewerSystem:
            return BridgeUpdateOffer(version: version, requiredSystemVersion: minimumSystemVersion)
        case .upToDate:
            return nil
        }
    }
}

/// When an automatic check is due. Automatic checks are off unless the
/// person turned them on; a manual check is always allowed.
enum BridgeUpdateSchedule {
    static let interval: TimeInterval = 24 * 60 * 60

    static func isDue(enabled: Bool, lastCheck: Date?, now: Date) -> Bool {
        guard enabled else { return false }
        guard let lastCheck else { return true }
        // A clock set back must not postpone the next check indefinitely.
        return now.timeIntervalSince(lastCheck) >= interval || lastCheck > now
    }
}

enum BridgeUpdateError: Error, Equatable, Sendable {
    case malformedManifest
    case unsupportedManifest
    case untrustedURL
    case httpStatus(Int)
    case network(String)
    case sizeMismatch
    case checksumMismatch
    case mountFailed(String)
    case applicationMissing
    case signatureInvalid(String)
    case wrongBundle
    case buildMismatch
    case notNotarized
    case notNewer
    case installFailed(String)
}

extension BridgeUpdateError: LocalizedError {
    var errorDescription: String? {
        switch self {
        case .malformedManifest, .unsupportedManifest:
            return InterfaceLanguage.text("The update information on dicavo.eu could not be read.")
        case .untrustedURL:
            return InterfaceLanguage.text("The update points somewhere other than dicavo.eu.")
        case let .httpStatus(status):
            return InterfaceLanguage.text("dicavo.eu answered with HTTP \(Int64(status)).")
        case let .network(message):
            return message
        case .sizeMismatch, .checksumMismatch:
            return InterfaceLanguage.text("The downloaded file does not match the published one.")
        case let .mountFailed(message):
            return InterfaceLanguage.text("The disk image could not be opened: \(message)")
        case .applicationMissing:
            return InterfaceLanguage.text("The disk image does not contain Dicavo CLI Bridge.")
        case let .signatureInvalid(message):
            return InterfaceLanguage.text("The downloaded app is not signed by the Dicavo developer: \(message)")
        case .wrongBundle, .buildMismatch:
            return InterfaceLanguage.text("The downloaded app is not the published version of Dicavo CLI Bridge.")
        case .notNotarized:
            return InterfaceLanguage.text("The downloaded app is not notarized by Apple.")
        case .notNewer:
            return InterfaceLanguage.text("The downloaded app is not newer than the one running.")
        case let .installFailed(message):
            return InterfaceLanguage.text("The update could not be installed: \(message)")
        }
    }
}
